theorem stationary_affine_density_iff {ε θ : ℝ → ℝ} {ℓ : ℝ}
    (hε : Continuous ε) (hθ : ContDiff ℝ 1 θ) (a b : ℝ) :
    Stationary (fun q => ε q + a * q + b) θ ℓ ↔ Stationary ε θ ℓ

theorem exists_correction_radius {a b : ℝ → ℝ}
    (ha : ContDiffAt ℝ 2 a 0) (hb : ContDiffAt ℝ 2 b 0) :
    ∃ r > 0, ∀ t ∈ Icc (-r) r, ContDiffAt ℝ 2 a t ∧ ContDiffAt ℝ 2 b t

theorem corrected_angle_hasDerivAt {θ η u v a b : ℝ → ℝ}
    (ha : HasDerivAt a 0 0) (hb : HasDerivAt b 0 0) (s : ℝ) :
    HasDerivAt (fun t => θ s + t * η s + a t * u s + b t * v s) (η s) 0

theorem hasDerivAt_exp_neg_mul {f : ℝ → ℝ} {x d : ℝ}
    (β : ℝ) (hf : HasDerivAt f d x) :
    HasDerivAt (fun t => exp (-β * f t)) (-β * exp (-β * f x) * d) x

theorem differentiableAt_exp_neg_mul_iff {f : ℝ → ℝ} {x β : ℝ}
    (hβ : β ≠ 0) :
    DifferentiableAt ℝ (fun t => exp (-β * f t)) x ↔ DifferentiableAt ℝ f x

theorem hasDerivAt_exp_neg_mul_zero_iff {f : ℝ → ℝ} {x β : ℝ}
    (hβ : β ≠ 0) :
    HasDerivAt (fun t => exp (-β * f t)) 0 x ↔ HasDerivAt f 0 x

theorem deriv_exp_neg_mul_eq_zero_iff {f : ℝ → ℝ} {β : ℝ}
    (hβ : β ≠ 0) (x : ℝ) :
    deriv (fun t => exp (-β * f t)) x = 0 ↔ deriv f x = 0

theorem hasDerivAt_powerLogDensity (p K : ℝ) {κ₀ κ : ℝ}
    (hκ₀ : 0 < κ₀) (hκ : 0 < κ) :
    HasDerivAt (powerLogDensity p K κ₀) (K * powerLog p (κ / κ₀)) κ

theorem second_deriv_powerLogDensity_pos (p : ℝ) {K κ₀ κ : ℝ}
    (hK : 0 < K) (hκ₀ : 0 < κ₀) (hκ : 0 < κ) :
    0 < deriv (deriv (powerLogDensity p K κ₀)) κ

theorem xCoord_eq_of_angle_eq {θ ψ : ℝ → ℝ} {ℓ s : ℝ}
    (h : EqOn ψ θ (Icc 0 ℓ)) (hs : s ∈ Icc 0 ℓ) (x₀ : ℝ) :
    xCoord ψ x₀ s = xCoord θ x₀ s

theorem yCoord_eq_of_angle_eq {θ ψ : ℝ → ℝ} {ℓ s : ℝ}
    (h : EqOn ψ θ (Icc 0 ℓ)) (hs : s ∈ Icc 0 ℓ) (y₀ : ℝ) :
    yCoord ψ y₀ s = yCoord θ y₀ s

theorem second_derivative_nonneg_of_local_min {f : ℝ → ℝ} {x q : ℝ}
    (hmin : IsLocalMin f x) (hc : ContinuousAt f x)
    (hsecond : HasDerivAt (deriv f) q x) : 0 ≤ q

theorem contDiff_angle_scaling {θ : ℝ → ℝ} {n : WithTop ℕ∞}
    (hθ : ContDiff ℝ n θ) (a : ℝ) :
    ContDiff ℝ n (fun s => θ (s / a))

theorem hasDerivAt_angle_scaling {θ : ℝ → ℝ} {a κ s : ℝ}
    (hθ : HasDerivAt θ κ (s / a)) :
    HasDerivAt (fun t => θ (t / a)) (κ / a) s

theorem locallyMinimizing_areaStationary {θ : ℝ → ℝ} {k ℓ : ℝ}
    (hℓ : 0 < ℓ) (hθ : ContDiff ℝ 3 θ) (hmin : LocallyMinimizing k θ ℓ) :
    LinearInputPressureStationary.AreaStationary k θ ℓ

theorem continuous_parameterLinear {η ξ₁ ξ₂ ξ₃ : ℝ → ℝ}
    (hη : Continuous η) (hξ₁ : Continuous ξ₁) (hξ₂ : Continuous ξ₂) (hξ₃ : Continuous ξ₃) :
    Continuous (parameterLinear η ξ₁ ξ₂ ξ₃)

theorem continuous_primitive_parameter {G : ℝ → ℝ → ℝ}
    (hG : Continuous (Function.uncurry G)) :
    Continuous (fun p : ℝ × ℝ => ∫ s in 0..p.2, G p.1 s)

theorem global_minimum_forces_input {lam r u a : ℝ}
    (hmin : ∀ t : ℝ, potential lam r u a ≤ potential lam r u t) :
    u = lam * a ^ 3 + r * a

theorem global_minimum_forces_design {lam r u a : ℝ}
    (hmin : ∀ x y : ℝ, E lam r u a (Real.sqrt 2 * a) ≤ E lam r u x y) :
    u = input lam r a

theorem hasDerivAt_internal {n : ℕ} {lam r u gamma target t : ℝ}
    {b : State n → ℝ} {kappa rho : Fin n → ℝ} {Phi : ℝ × ℝ → (Fin n → ℝ)}
    {q : ℝ → State n}
    (hq : HasDerivAt q (vectorField lam r u gamma target b kappa rho Phi (q t)) t)
    (i : Fin n) :
    HasDerivAt (fun s => (q s).2 i)
      (-kappa i * (q t).2 i + rho i * Phi (q t).1 i) t

theorem hasDerivAt_energy {n : ℕ} {lam r u gamma target t : ℝ}
    {b : State n → ℝ} {kappa rho : Fin n → ℝ} {Phi : ℝ × ℝ → (Fin n → ℝ)}
    {q : ℝ → State n}
    (hq : HasDerivAt q (vectorField lam r u gamma target b kappa rho Phi (q t)) t) :
    HasDerivAt (fun s => E lam r u (q s).1.1 (q s).1.2)
      (-gamma * (E lam r u (q t).1.1 (q t).1.2 - target) *
        gSq lam r u (q t).1.1 (q t).1.2) t

theorem isTrajectory_of_global_solution {n : ℕ} {lam r u gamma target : ℝ}
    {b : State n → ℝ} {kappa rho : Fin n → ℝ} {Phi : ℝ × ℝ → (Fin n → ℝ)}
    {q : ℝ → State n}
    (hq : ∀ t ∈ Ici (0 : ℝ),
      HasDerivAt q (vectorField lam r u gamma target b kappa rho Phi (q t)) t) :
    IsTrajectory lam r u gamma target (fun t => (q t).1.1) (fun t => (q t).1.2)
      (fun t => b (q t))

theorem solution_unique_on_Ici {n : ℕ} {lam r u gamma target : ℝ}
    {b : State n → ℝ} {kappa rho : Fin n → ℝ} {Phi : ℝ × ℝ → (Fin n → ℝ)}
    (hb : ContDiff ℝ 1 b) (hPhi : ContDiff ℝ 1 Phi) {q v : ℝ → State n}
    (hq : ∀ t ∈ Ici (0 : ℝ),
      HasDerivAt q (vectorField lam r u gamma target b kappa rho Phi (q t)) t)
    (hv : ∀ t ∈ Ici (0 : ℝ),
      HasDerivAt v (vectorField lam r u gamma target b kappa rho Phi (v t)) t)
    (heq : q 0 = v 0) : EqOn q v (Ici (0 : ℝ))

theorem contDiff_finite_expansion {n : ℕ} {m : WithTop ℕ∞}
    {psi : Fin n → (ℝ × ℝ) → ℝ} (hpsi : ∀ i, ContDiff ℝ m (psi i)) :
    ContDiff ℝ m (fun q : State n => ∑ i, q.2 i * psi i q.1)

theorem coordinate_solution_unique_on_Ici {b : ℝ × ℝ → ℝ}
    (hb : ContDiff ℝ 1 b) {lam r u gamma target : ℝ}
    {x₁ y₁ x₂ y₂ : ℝ → ℝ}
    (h₁ : IsTrajectory lam r u gamma target x₁ y₁ (fun t => b (x₁ t, y₁ t)))
    (h₂ : IsTrajectory lam r u gamma target x₂ y₂ (fun t => b (x₂ t, y₂ t)))
    (hx : x₁ 0 = x₂ 0) (hy : y₁ 0 = y₂ 0) :
    EqOn x₁ x₂ (Ici (0 : ℝ)) ∧ EqOn y₁ y₂ (Ici (0 : ℝ))

theorem explicit_gradient_bound_pos {lam r u target upper : ℝ}
    (htarget : (max (-r) 0) ^ 2 / (12 * lam) < target) :
    0 < gradientLowerBound lam r u target upper

theorem exists_unique_global_minimum_of_input_ne_zero {lam r u : ℝ}
    (hlam : 0 < lam) (hu : u ≠ 0) :
    ∃! z : ℝ × ℝ, ∀ w : ℝ × ℝ, E lam r u z.1 z.2 ≤ E lam r u w.1 w.2

theorem continuousOn_gradient_coefficient {lam r u gamma target : ℝ}
    {x y b : ℝ → ℝ} (htraj : IsTrajectory lam r u gamma target x y b) :
    ContinuousOn (fun t => gSq lam r u (x t) (y t)) (Ici (0 : ℝ))

theorem contDiff_vectorField {n : WithTop ℕ∞} {b : ℝ × ℝ → ℝ}
    (hb : ContDiff ℝ n b) (lam r u gamma target : ℝ) :
    ContDiff ℝ n (vectorField lam r u gamma target b)

theorem hasDerivAt_energy_of_solution {lam r u gamma target : ℝ}
    {b : ℝ × ℝ → ℝ} {z : ℝ → ℝ × ℝ} {t : ℝ}
    (hz : HasDerivAt z (vectorField lam r u gamma target b (z t)) t) :
    HasDerivAt (fun s => E lam r u (z s).1 (z s).2)
      (-gamma * (E lam r u (z t).1 (z t).2 - target) *
        gSq lam r u (z t).1 (z t).2) t

theorem isTrajectory_of_global_solution {lam r u gamma target : ℝ}
    {b : ℝ × ℝ → ℝ} {z : ℝ → ℝ × ℝ}
    (hz : ∀ t ∈ Ici (0 : ℝ), HasDerivAt z (vectorField lam r u gamma target b (z t)) t) :
    IsTrajectory lam r u gamma target (fun t => (z t).1) (fun t => (z t).2)
      (fun t => b (z t))

theorem stationary_linear_density_iff {ε θ : ℝ → ℝ} {ℓ : ℝ}
    (hε : Continuous ε) (hθ : ContDiff ℝ 1 θ) (u : ℝ) :
    Stationary (fun q => ε q - u * q) θ ℓ ↔ Stationary ε θ ℓ
